import { useState, useEffect, useCallback } from 'react'
import { Box, Button, Divider, Group, Modal, Stack, Text, TextInput } from '@mantine/core'
import { notifications } from '@mantine/notifications'
import ThumbnailPanel from './ThumbnailPanel'
import DetailPanel from '../DetailPanel'
import { OpenFile, OpenPDF, PageCount, PickFolder, ExportSplit, CheckConflicts, DeleteFile } from '../../../wailsjs/go/main/App'
import { ellipsisPath } from '../../utils'
import { useOutputFiles } from './useOutputFiles'
import { usePendingFocus } from './usePendingFocus'

const DEFAULT_TEMPLATE = '{date} {name}'

function applyTemplate(template: string): { value: string; cursorPos: number } {
  const date = new Date().toISOString().split('T')[0]
  const withDate = template.replace('{date}', date)
  const nameIdx = withDate.indexOf('{name}')
  if (nameIdx === -1) return { value: withDate, cursorPos: withDate.length }
  return { value: withDate.replace('{name}', ''), cursorPos: nameIdx }
}

interface Props {
  initialPath?: string | null
}

export default function SplitMode({ initialPath }: Props) {
  const [pdfPath, setPdfPath] = useState<string | null>(null)
  const [pageCount, setPageCount] = useState(0)
  const [pageOrder, setPageOrder] = useState<number[]>([])
  const [selectedPage, setSelectedPage] = useState(1)
  const [outputFolder, setOutputFolder] = useState<string | null>(null)
  const [successModal, setSuccessModal] = useState<{show: boolean, outputPath: string, inputPath: string}>({show: false, outputPath: '', inputPath: ''})
  const outputFiles = useOutputFiles(outputFolder)
  const focus = usePendingFocus()
  const [template, setTemplate] = useState(DEFAULT_TEMPLATE)
  const [exporting, setExporting] = useState(false)
  const [rotations, setRotations] = useState<Map<number, number>>(() => new Map())
  const [skipped, setSkipped] = useState<Set<number>>(() => new Set())

  const rotate = (page: number) => {
    setRotations(prev => {
      const next = new Map(prev)
      const deg = ((next.get(page) ?? 0) + 90) % 360
      if (deg === 0) next.delete(page); else next.set(page, deg)
      return next
    })
  }

  const toggleSkip = (page: number) => {
    setSkipped(prev => {
      const next = new Set(prev)
      if (next.has(page)) next.delete(page); else next.add(page)
      return next
    })
  }

  const movePage = (fromPos: number, toPos: number) => {
    setPageOrder(prev => {
      const next = [...prev]
      const [page] = next.splice(fromPos, 1)
      next.splice(toPos, 0, page)
      return next
    })
  }

  const resetForFile = (count: number, path: string, tmpl: string) => {
    setPdfPath(path)
    setPageCount(count)
    setPageOrder(Array.from({ length: count }, (_, i) => i + 1))
    setSelectedPage(1)
    setRotations(new Map())
    setSkipped(new Set())
    outputFiles.reset(applyTemplate(tmpl).value)
    focus.clear()
  }

  useEffect(() => {
    if (!initialPath) return
    PageCount(initialPath)
      .then(count => resetForFile(count, initialPath, template))
      .catch(e => notifications.show({ title: 'Failed to open file', message: String(e), color: 'red' }))
  }, [initialPath])

  const handleOpen = async () => {
    const path = await OpenPDF()
    if (!path) return
    try {
      const count = await PageCount(path)
      resetForFile(count, path, template)
    } catch (e) {
      notifications.show({ title: 'Failed to open file', message: String(e), color: 'red' })
    }
  }

  const handlePickOutputFolder = async () => {
    const folder = await PickFolder()
    if (folder) setOutputFolder(folder)
  }

  const handleExport = async () => {
    if (!pdfPath || !outputFolder) return
    setExporting(true)
    try {
      const sortedStarts = [...outputFiles.all.keys()].sort((a, b) => a - b)
      const files = sortedStarts.map((firstPos, i) => {
        const nextPos = sortedStarts[i + 1] ?? pageOrder.length
        const pages = pageOrder.slice(firstPos, nextPos).filter(p => !skipped.has(p))
        const f = outputFiles.all.get(firstPos)!
        return { pages, name: f.name, outDir: f.folderOverride ?? outputFolder! }
      })
      const conflicts = await CheckConflicts(files)
      if (conflicts.length > 0) {
        const names = conflicts.map(p => p.split('/').pop()).join(', ')
        notifications.show({ title: 'Filename conflict', message: `Already exists: ${names}`, color: 'orange', autoClose: false })
        return
      }
      await ExportSplit(pdfPath, files, Object.fromEntries(rotations))
      setSuccessModal({show: true, outputPath: outputFolder, inputPath: pdfPath})
    } catch (e) {
      notifications.show({ title: 'Export failed', message: String(e), color: 'red' })
    } finally {
      setExporting(false)
    }
  }

  const closeSuccessModal = () => setSuccessModal({show: false, outputPath: '', inputPath: ''})

  const handleDeleteInput = async () => {
    const { inputPath } = successModal
    closeSuccessModal()
    setPdfPath(null)
    try {
      await DeleteFile(inputPath)
    } catch (e) {
      notifications.show({ title: 'Failed to delete file', message: String(e), color: 'red' })
    }
  }

  const handleToggleSplitPoint = useCallback((afterPosition: number) => {
    const prefill = applyTemplate(template)
    const added = outputFiles.toggle(afterPosition, prefill.value)
    if (added) focus.request(afterPosition, prefill.cursorPos)
    else focus.clear()
  }, [template, outputFiles.toggle])

  return (
    <Box style={{ display: 'flex', flexDirection: 'column', height: '100%' }}>
      <Modal opened={successModal.show} onClose={closeSuccessModal} title="Export complete" centered>
        <Stack gap="md">
          <Group>
            <Text size="sm" c="dimmed" style={{ flex: 1 }}>{successModal.outputPath}</Text>
            <Button size="xs" variant="default" onClick={() => OpenFile(successModal.outputPath)}>
              Open in Finder
            </Button>
          </Group>
          <Divider />
          <div>
            <Text size="sm" mb={4}>What do you want to do with the input file?</Text>
            <Text size="sm" c="dimmed" mb="sm">{successModal.inputPath.split('/').pop()}</Text>
            <Group>
              <Button variant="default" onClick={closeSuccessModal}>Keep</Button>
              <Button color="red" onClick={handleDeleteInput}>Delete</Button>
            </Group>
          </div>
        </Stack>
      </Modal>
      <Box
        style={{
          flexShrink: 0,
          borderBottom: '1px solid var(--mantine-color-gray-3)',
          display: 'flex',
          alignItems: 'center',
          paddingInline: 12,
          height: 44,
        }}
      >
        <Group gap={8} style={{ width: '100%' }}>
          <Button size="xs" variant="default" onClick={handleOpen}>
            Open PDF
          </Button>
          <TextInput
            size="xs"
            placeholder={DEFAULT_TEMPLATE}
            value={template}
            onChange={(e) => setTemplate(e.currentTarget.value)}
            leftSection={<span style={{ fontSize: 11, whiteSpace: 'nowrap', color: 'var(--mantine-color-dimmed)' }}>Template</span>}
            leftSectionWidth={60}
            style={{ flex: 1 }}
          />
          <Button size="xs" variant="default" onClick={handlePickOutputFolder}>
            {outputFolder ? ellipsisPath(outputFolder) : 'Output folder…'}
          </Button>
          <Button size="xs" disabled={!pdfPath || !outputFolder || outputFiles.duplicateFirstPages.size > 0} loading={exporting} onClick={handleExport}>
            Export
          </Button>
        </Group>
      </Box>

      <Box style={{ flex: 1, overflow: 'hidden', display: 'flex' }}>
        {pdfPath ? (
          <>
            <ThumbnailPanel
              pdfPath={pdfPath}
              pageOrder={pageOrder}
              selectedPage={selectedPage}
              onSelectPage={setSelectedPage}
              onToggleSplitPoint={handleToggleSplitPoint}
              outputFiles={outputFiles}
              outputFolder={outputFolder}
              focus={focus}
              rotations={rotations}
              onRotate={rotate}
              skipped={skipped}
              onToggleSkip={toggleSkip}
              onMovePage={movePage}
            />
            <DetailPanel
              pdfPath={pdfPath}
              pageNum={selectedPage}
              pageCount={pageCount}
              rotation={rotations.get(selectedPage) ?? 0}
              onRotate={() => rotate(selectedPage)}
              onNavigate={setSelectedPage}
            />
          </>
        ) : (
          <Box style={{ flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
            <Button onClick={handleOpen}>Open PDF</Button>
          </Box>
        )}
      </Box>
    </Box>
  )
}

import { useState, useEffect } from 'react'
import { Box, Button, Checkbox, Group, Modal, SegmentedControl, Text, Tooltip } from '@mantine/core'
import { notifications } from '@mantine/notifications'
import { IconAlertTriangle } from '@tabler/icons-react'
import { MergePDFs, OpenFile, SavePDF } from '../../../wailsjs/go/main/App'
import MergeModeThumbnailPanel, { DEFAULT_TOTAL_WIDTH, FirstPageIn, SelectedPage } from './ThumbnailPanel'
import DetailPanel from '../DetailPanel'
import { usePDFFile } from '../../hooks/usePDFFile'
import * as pageCache from '../../hooks/pageCache'
import { basename } from '../../utils'

interface Props {
  onOpenInSplitMode: (path: string) => void
}

export default function MergeMode({ onOpenInSplitMode }: Props) {
  const fileA = usePDFFile()
  const fileB = usePDFFile()
  const [selectedPage, setSelectedPage] = useState<SelectedPage>({ file: 'a', page: 1 })
  const [firstPageIn, setFirstPageIn] = useState<FirstPageIn>('a')
  const [reverseB, setReverseB] = useState(true)
  const [merging, setMerging] = useState(false)
  const [mergedPath, setMergedPath] = useState<string | null>(null)
  const [totalWidth, setTotalWidth] = useState(DEFAULT_TOTAL_WIDTH)

  useEffect(() => {
    return () => {
      if (fileA.path) pageCache.evict(fileA.path)
      if (fileB.path) pageCache.evict(fileB.path)
    }
  }, [fileA.path, fileB.path])

  // Subtract 22px to account for scrollbar + gap
  const colWidth = Math.floor((totalWidth - 22) / 2)

  const handleChoose = async (file: FirstPageIn) => {
    const loaded = await (file === 'a' ? fileA : fileB).load()
    if (loaded) setSelectedPage({ file, page: 1 })
  }

  const handleMerge = async () => {
    if (!fileA.path || !fileB.path) return
    const outPath = await SavePDF()
    if (!outPath) return
    setMerging(true)
    try {
      await MergePDFs(
        fileA.path, fileB.path, outPath,
        firstPageIn === 'a', reverseB,
        [...fileA.skipped], [...fileB.skipped],
        Object.fromEntries(fileA.rotations), Object.fromEntries(fileB.rotations),
      )
      setMergedPath(outPath)
    } catch (e) {
      notifications.show({ title: 'Merge failed', message: String(e), color: 'red' })
    } finally {
      setMerging(false)
    }
  }

  const bothLoaded = fileA.path !== null && fileB.path !== null
  const unequalCounts = bothLoaded && fileA.count !== fileB.count
  const selectedFile = selectedPage.file === 'a' ? fileA : fileB
  const selectedPath = selectedFile.path
  const selectedCount = selectedFile.count

  return (
    <Box style={{ display: 'flex', flexDirection: 'column', height: '100%' }}>
      <Modal opened={mergedPath !== null} onClose={() => setMergedPath(null)} title="Merge complete" centered>
        <Text size="sm" c="dimmed" mb="md">{mergedPath}</Text>
        <Group>
          <Button variant="default" onClick={() => OpenFile(mergedPath!)}>
            Open in Default App
          </Button>
          <Button onClick={() => { onOpenInSplitMode(mergedPath!); setMergedPath(null) }}>
            Open in Split Mode
          </Button>
        </Group>
      </Modal>
      <Box
        style={{
          flexShrink: 0,
          borderBottom: '1px solid var(--mantine-color-gray-3)',
          display: 'flex',
          alignItems: 'stretch',
        }}
      >
        <FilePickerColumn label="File A" path={fileA.path} width={colWidth} onChoose={() => handleChoose('a')} />
        {/* Add 26 px to account for scrollbar + gap */}
        <FilePickerColumn label="File B" path={fileB.path} width={colWidth + 26} onChoose={() => handleChoose('b')} />
        <Group gap={8} px={12} style={{ flex: 1, justifyContent: 'flex-end' }}>
          {unequalCounts && (
            <Tooltip
              label={`File A has ${fileA.count} page${fileA.count !== 1 ? 's' : ''}, File B has ${fileB.count} page${fileB.count !== 1 ? 's' : ''}. The extra ${Math.abs(fileA.count - fileB.count)} page${Math.abs(fileA.count - fileB.count) !== 1 ? 's' : ''} will be appended at the end.`}
              multiline
              w={280}
            >
              <IconAlertTriangle size={18} color="var(--mantine-color-yellow-6)" />
            </Tooltip>
          )}
          <Checkbox
            size="sm"
            label="Reverse File B"
            checked={reverseB}
            onChange={(e) => setReverseB(e.currentTarget.checked)}
          />
          <Text size="sm" c="dimmed">First page in</Text>
          <SegmentedControl
            size="xs"
            value={firstPageIn}
            onChange={(v) => setFirstPageIn(v as FirstPageIn)}
            data={[
              { label: 'File A', value: 'a' },
              { label: 'File B', value: 'b' },
            ]}
          />
          <Button size="sm" disabled={!bothLoaded} loading={merging} onClick={handleMerge}>
            Merge & Save
          </Button>
        </Group>
      </Box>

      <Box style={{ flex: 1, overflow: 'hidden', display: 'flex' }}>
        <MergeModeThumbnailPanel
          fileA={fileA}
          fileB={fileB}
          selectedPage={selectedPage}
          onSelectPage={(file, page) => setSelectedPage({ file, page })}
          firstPageIn={firstPageIn}
          totalWidth={totalWidth}
          onWidthChange={setTotalWidth}
          colWidth={colWidth}
          reverseB={reverseB}
        />
        {selectedPath && (
          <DetailPanel
            pdfPath={selectedPath}
            pageNum={selectedPage.page}
            pageCount={selectedCount}
            rotation={selectedFile.rotations.get(selectedPage.page) ?? 0}
            onNavigate={(page) => setSelectedPage({ file: selectedPage.file, page })}
            onToggleSkip={() => selectedFile.toggleSkip(selectedPage.page)}
            onRotate={() => selectedFile.rotate(selectedPage.page)}
          />
        )}
      </Box>
    </Box>
  )
}

function FilePickerColumn({
  label, path, width, onChoose,
}: {
  label: string
  path: string | null
  width: number
  onChoose: () => void
}) {
  return (
    <Box
      style={{
        width,
        flexShrink: 0,
        padding: '6px 8px',
        borderRight: '1px solid var(--mantine-color-gray-3)',
        display: 'flex',
        flexDirection: 'column',
        justifyContent: 'center',
        gap: 2,
      }}
    >
      <Group justify="space-between" gap={4} wrap="nowrap">
        <Text size="xs" c="dimmed">{label}</Text>
        <Button size="xs" variant="default" onClick={onChoose}>Choose…</Button>
      </Group>
      <Text
        size="xs"
        style={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}
        title={path ?? undefined}
      >
        {path ? basename(path) : '—'}
      </Text>
    </Box>
  )
}

import { useState, useCallback, useMemo } from 'react'
import { PickFolder } from '../../../wailsjs/go/main/App'

export interface OutputFile {
  name: string
  folderOverride?: string
}

// Keyed by firstPosition (0-indexed position in pageOrder). Position 0 is always present.
type OutputFilesMap = Map<number, OutputFile>

export interface OutputFilesHandle {
  all: OutputFilesMap
  duplicateFirstPages: Set<number>
  getSplitPoints: () => Set<number>
  toggle: (afterPosition: number, prefillName: string) => boolean
  setName: (firstPosition: number, name: string) => void
  pickFolderOverride: (firstPosition: number) => Promise<void>
  reset: (firstPageName: string) => void
}

export function useOutputFiles(outputFolder: string | null): OutputFilesHandle {
  const [files, setFiles] = useState<OutputFilesMap>(new Map([[0, { name: '' }]]))

  const toggle = (afterPosition: number, prefillName: string): boolean => {
    const firstPosition = afterPosition + 1
    const adding = !files.has(firstPosition)
    setFiles(prev => {
      const next = new Map(prev)
      if (next.has(firstPosition)) {
        next.delete(firstPosition)
      } else {
        next.set(firstPosition, { name: prefillName })
      }
      return next
    })
    return adding
  }

  const setName = useCallback((firstPosition: number, name: string) => {
    setFiles(prev => {
      const entry = prev.get(firstPosition)
      if (!entry) return prev
      return new Map(prev).set(firstPosition, { ...entry, name })
    })
  }, [])

  const pickFolderOverride = useCallback(async (firstPosition: number) => {
    const folder = await PickFolder()
    if (!folder) return
    setFiles(prev => {
      const entry = prev.get(firstPosition)
      if (!entry) return prev
      return new Map(prev).set(firstPosition, { ...entry, folderOverride: folder })
    })
  }, [])

  const reset = useCallback((firstPageName: string) => {
    setFiles(new Map([[0, { name: firstPageName }]]))
  }, [])

  const duplicateFirstPages = useMemo(() => {
    const seen = new Map<string, number>()
    const dupes = new Set<number>()
    for (const [firstPosition, file] of files.entries()) {
      const folder = file.folderOverride ?? outputFolder ?? ''
      const key = `${folder}::${file.name}`
      if (seen.has(key)) {
        dupes.add(firstPosition)
        dupes.add(seen.get(key)!)
      } else {
        seen.set(key, firstPosition)
      }
    }
    return dupes
  }, [files, outputFolder])

  // Returns positions after which a split occurs (i.e., firstPosition - 1 for each section > 0).
  const getSplitPoints = () => {
    const result = new Set<number>()
    for (const firstPosition of files.keys()) {
      if (firstPosition > 0) result.add(firstPosition - 1)
    }
    return result
  }

  return {
    all: files,
    duplicateFirstPages,
    getSplitPoints,
    toggle,
    setName,
    pickFolderOverride,
    reset,
  }
}

import { useState, useCallback } from 'react'

export interface PendingFocusHandle {
  pendingFocus: { afterPosition: number; cursorPos: number } | null
  clear: () => void
  request: (afterPosition: number, cursorPos: number) => void
}

// Tracks which filename input should steal focus after a split point is added,
// and where the cursor should land within it. Cleared by the input itself once
// it has focused, so only the first render after the split point is added fires.
export function usePendingFocus(): PendingFocusHandle {
  const [pendingFocus, setPendingFocus] = useState<{ afterPosition: number; cursorPos: number } | null>(null)
  const request = useCallback((afterPosition: number, cursorPos: number) => setPendingFocus({ afterPosition, cursorPos }), [])
  const clear = useCallback(() => setPendingFocus(null), [])
  return { pendingFocus, request, clear }
}

