import { useRef, useState, useEffect, useMemo } from 'react'
import { useVirtualizer } from '@tanstack/react-virtual'
import { DndContext, DragOverlay, PointerSensor, closestCenter, useSensor, useSensors } from '@dnd-kit/core'
import type { DragEndEvent } from '@dnd-kit/core'
import { SortableContext, useSortable, verticalListSortingStrategy } from '@dnd-kit/sortable'
import { CSS } from '@dnd-kit/utilities'
import * as pageCache from '../../hooks/pageCache'
import { DEFAULT_WIDTH, DRAG_HANDLE_WIDTH, ITEM_PADDING, PAGE_ASPECT, LABEL_HEIGHT, HEADER_HEIGHT } from '../../constants'
import PageThumbnail from '../PageThumbnail'
import type { OutputFilesHandle } from './useOutputFiles'
import OutputFileHeader from './OutputFileHeader'
import type { PendingFocusHandle } from './usePendingFocus'

const MIN_WIDTH = 120
const MAX_WIDTH = 480
const GAP_HEIGHT = 16

type ListItem =
  | { type: 'header'; fileIndex: number; firstPosition: number }
  | { type: 'page'; page: number; position: number }

function buildItems(pageOrder: number[], splitPoints: Set<number>): ListItem[] {
  const result: ListItem[] = []
  let fileIndex = 0
  for (let pos = 0; pos < pageOrder.length; pos++) {
    if (pos === 0 || splitPoints.has(pos - 1)) {
      result.push({ type: 'header', fileIndex: fileIndex++, firstPosition: pos })
    }
    result.push({ type: 'page', page: pageOrder[pos], position: pos })
  }
  return result
}

interface Props {
  pdfPath: string
  pageOrder: number[]
  selectedPage: number
  onSelectPage: (page: number) => void
  onToggleSplitPoint: (afterPosition: number) => void
  outputFiles: OutputFilesHandle
  outputFolder: string | null
  focus: PendingFocusHandle
  rotations: Map<number, number>
  onRotate: (page: number) => void
  skipped: Set<number>
  onToggleSkip: (page: number) => void
  onMovePage: (fromPos: number, toPos: number) => void
}

export default function SplitThumbnailPanel({
  pdfPath, pageOrder, selectedPage, onSelectPage,
  onToggleSplitPoint,
  outputFiles,
  outputFolder,
  focus,
  rotations,
  onRotate,
  skipped,
  onToggleSkip,
  onMovePage,
}: Props) {
  const [panelWidth, setPanelWidth] = useState(DEFAULT_WIDTH)
  const [hoveredGap, setHoveredGap] = useState<number | null>(null)
  const [hoveredPage, setHoveredPage] = useState<number | null>(null)
  const [activeId, setActiveId] = useState<number | null>(null)
  const sensors = useSensors(useSensor(PointerSensor, { activationConstraint: { distance: 8 } }))

  const thumbWidth = panelWidth - ITEM_PADDING * 2
  const thumbHeight = Math.round(thumbWidth * PAGE_ASPECT)
  const pageItemHeight = thumbHeight + LABEL_HEIGHT + ITEM_PADDING + GAP_HEIGHT

  const splitPoints = useMemo(() => outputFiles.getSplitPoints(), [outputFiles.all])
  const items = useMemo(() => buildItems(pageOrder, splitPoints), [pageOrder, splitPoints])
  // Ref so the scroll effect can read the current list without depending on it
  // (we don't want to re-scroll every time a split point is toggled).
  const itemsRef = useRef(items)
  itemsRef.current = items

  const scrollRef = useRef<HTMLDivElement>(null)

  const virtualizer = useVirtualizer({
    count: items.length,
    getScrollElement: () => scrollRef.current,
    estimateSize: (index) => items[index]?.type === 'header' ? HEADER_HEIGHT : pageItemHeight,
    overscan: 3,
  })

  useEffect(() => {
    virtualizer.measure()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [items.length, pageItemHeight])

  const virtualItems = virtualizer.getVirtualItems()
  pageCache.usePageCacheRender()

  useEffect(() => {
    for (const vItem of virtualItems) {
      const item = items[vItem.index]
      if (item.type === 'page') pageCache.load(pdfPath, item.page, thumbWidth)
    }
  })

  useEffect(() => {
    const index = itemsRef.current.findIndex(item => item.type === 'page' && item.page === selectedPage)
    if (index >= 0) virtualizer.scrollToIndex(index, { align: 'auto' })
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedPage])

  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return
      const selectedPos = pageOrder.indexOf(selectedPage)
      if (e.key === 'ArrowLeft') {
        e.preventDefault()
        if (selectedPos > 0) onSelectPage(pageOrder[selectedPos - 1])
      } else if (e.key === 'ArrowRight') {
        e.preventDefault()
        if (selectedPos < pageOrder.length - 1) onSelectPage(pageOrder[selectedPos + 1])
      } else if (e.key === 'Delete' || e.key === 'Backspace') {
        e.preventDefault()
        onToggleSkip(selectedPage)
      }
    }
    window.addEventListener('keydown', handler)
    return () => window.removeEventListener('keydown', handler)
  }, [selectedPage, pageOrder, onSelectPage, onToggleSkip])

  const handleDragEnd = ({ active, over }: DragEndEvent) => {
    setActiveId(null)
    if (!over || active.id === over.id) return
    const fromPos = pageOrder.indexOf(active.id as number)
    const toPos = pageOrder.indexOf(over.id as number)
    if (fromPos !== -1 && toPos !== -1) onMovePage(fromPos, toPos)
  }

  const startDrag = (e: React.MouseEvent) => {
    const startX = e.clientX
    const startWidth = panelWidth
    const clamp = (w: number) => Math.max(MIN_WIDTH, Math.min(MAX_WIDTH, w))
    const onMove = (ev: MouseEvent) => setPanelWidth(clamp(startWidth + ev.clientX - startX))
    const onUp = (ev: MouseEvent) => {
      setPanelWidth(clamp(startWidth + ev.clientX - startX))
      document.removeEventListener('mousemove', onMove)
      document.removeEventListener('mouseup', onUp)
    }
    document.addEventListener('mousemove', onMove)
    document.addEventListener('mouseup', onUp)
    e.preventDefault()
  }

  return (
    <div style={{ display: 'flex', height: '100%', flexShrink: 0 }}>
      <div style={{ display: 'flex', flexDirection: 'column', width: panelWidth, height: '100%' }}>
        <DndContext
          sensors={sensors}
          collisionDetection={closestCenter}
          onDragStart={({ active }) => setActiveId(active.id as number)}
          onDragEnd={handleDragEnd}
        >
          <SortableContext items={pageOrder} strategy={verticalListSortingStrategy}>
            <div
              ref={scrollRef}
              style={{
                flex: 1,
                minHeight: 0,
                overflowY: 'auto',
                overflowX: 'hidden',
                background: 'var(--mantine-color-gray-3)',
              }}
            >
              <div style={{ height: virtualizer.getTotalSize(), position: 'relative' }}>
                {virtualItems.map(vItem => {
                  const item = items[vItem.index]

                  if (item.type === 'header') {
                    return (
                      <div
                        key={vItem.key}
                        style={{ position: 'absolute', top: vItem.start, left: 0, width: '100%', height: vItem.size }}
                      >
                        <OutputFileHeader
                          filename={outputFiles.all.get(item.firstPosition)?.name ?? ''}
                          onChange={(name) => outputFiles.setName(item.firstPosition, name)}
                          firstPosition={item.firstPosition}
                          focus={focus}
                          folder={outputFiles.all.get(item.firstPosition)?.folderOverride ?? outputFolder}
                          onPickFolder={() => outputFiles.pickFolderOverride(item.firstPosition)}
                          isDuplicate={outputFiles.duplicateFirstPages.has(item.firstPosition)}
                        />
                      </div>
                    )
                  }

                  const { page, position } = item
                  const isSplit = splitPoints.has(position)
                  const isLastPage = position === pageOrder.length - 1

                  return (
                    <div
                      key={vItem.key}
                      style={{
                        position: 'absolute',
                        top: vItem.start,
                        left: 0,
                        width: '100%',
                        height: vItem.size,
                        boxSizing: 'border-box',
                      }}
                      onMouseEnter={() => setHoveredPage(page)}
                      onMouseLeave={() => setHoveredPage(null)}
                    >
                      <SortablePageItem id={page}>
                        <PageThumbnail
                          src={pageCache.getSrc(pdfPath, page)}
                          pdfPath={pdfPath}
                          page={page}
                          thumbHeight={thumbHeight}
                          isSelected={page === selectedPage}
                          isSkipped={skipped.has(page)}
                          rotation={rotations.get(page) ?? 0}
                          isHovered={hoveredPage === page}
                          label={String(page)}
                          onClick={() => onSelectPage(page)}
                          onRotate={() => onRotate(page)}
                          onToggleSkip={() => onToggleSkip(page)}
                          canMoveUp={position > 0}
                          canMoveDown={!isLastPage}
                          onMoveUp={() => onMovePage(position, position - 1)}
                          onMoveDown={() => onMovePage(position, position + 1)}
                        />
                      </SortablePageItem>
                      {!isLastPage && (
                        <GapZone
                          isSplit={isSplit}
                          isHovered={hoveredGap === position}
                          onClick={(e) => { e.stopPropagation(); onToggleSplitPoint(position) }}
                          onMouseEnter={() => setHoveredGap(position)}
                          onMouseLeave={() => setHoveredGap(null)}
                        />
                      )}
                    </div>
                  )
                })}
              </div>
            </div>
          </SortableContext>
          <DragOverlay>
            {activeId !== null && (
              <PageThumbnail
                src={pageCache.getSrc(pdfPath, activeId)}
                pdfPath={pdfPath}
                page={activeId}
                thumbHeight={thumbHeight}
                isSelected={false}
                isSkipped={skipped.has(activeId)}
                rotation={rotations.get(activeId) ?? 0}
                isHovered={false}
                label={String(activeId)}
                onClick={() => {}}
                onRotate={() => {}}
                onToggleSkip={() => {}}
              />
            )}
          </DragOverlay>
        </DndContext>
      </div>

      <div
        onMouseDown={startDrag}
        style={{
          width: DRAG_HANDLE_WIDTH,
          height: '100%',
          cursor: 'col-resize',
          flexShrink: 0,
          background: 'var(--mantine-color-gray-3)',
        }}
      />
    </div>
  )
}

function SortablePageItem({ id, children }: { id: number; children: React.ReactNode }) {
  const { setNodeRef, transform, isDragging, attributes, listeners } = useSortable({ id })
  return (
    <div
      ref={setNodeRef}
      style={{ transform: CSS.Transform.toString(transform), opacity: isDragging ? 0 : 1 }}
      {...attributes}
      {...listeners}
    >
      {children}
    </div>
  )
}

interface GapZoneProps {
  isSplit: boolean
  isHovered: boolean
  onClick: (e: React.MouseEvent) => void
  onMouseEnter: () => void
  onMouseLeave: () => void
}

function GapZone({ isSplit, isHovered, onClick, onMouseEnter, onMouseLeave }: GapZoneProps) {
  const bg = isSplit
    ? 'var(--mantine-color-blue-0)'
    : isHovered
    ? 'var(--mantine-color-gray-2)'
    : undefined

  return (
    <div
      onClick={onClick}
      onMouseEnter={onMouseEnter}
      onMouseLeave={onMouseLeave}
      style={{
        height: GAP_HEIGHT,
        background: bg,
        display: 'flex',
        alignItems: 'center',
        paddingLeft: ITEM_PADDING,
        paddingRight: ITEM_PADDING,
        cursor: 'pointer',
      }}
    >
      {isSplit && (
        <div style={{ flex: 1, height: 2, background: 'var(--mantine-color-blue-5)', borderRadius: 1 }} />
      )}
      {!isSplit && isHovered && (
        <div style={{ flex: 1, height: 0, borderTop: '1px dashed var(--mantine-color-gray-5)' }} />
      )}
    </div>
  )
}

import { Loader } from '@mantine/core'
import { IconRotateClockwise, IconX, IconArrowUp, IconArrowDown } from '@tabler/icons-react'
import * as pageCache from '../hooks/pageCache'
import { ITEM_PADDING, LABEL_HEIGHT } from '../constants'

interface Props {
  src: string | undefined
  pdfPath: string
  page: number
  thumbHeight: number
  isSelected: boolean
  isSkipped: boolean
  rotation: number
  isHovered: boolean
  label: string
  onClick: () => void
  onRotate: () => void
  onToggleSkip: () => void
  canMoveUp?: boolean
  canMoveDown?: boolean
  onMoveUp?: () => void
  onMoveDown?: () => void
}

export default function PageThumbnail({
  src, pdfPath, page, thumbHeight,
  isSelected, isSkipped, rotation,
  isHovered, label,
  onClick, onRotate, onToggleSkip,
  canMoveUp, canMoveDown, onMoveUp, onMoveDown,
}: Props) {
  const isRotated = rotation !== 0
  const showRotateBtn = isHovered || isRotated
  const isOddRotation = rotation === 90 || rotation === 270
  const imgTransform = rotation ? `rotate(${rotation}deg)${isOddRotation ? ` scale(${210 / 297})` : ''}` : undefined
  const showSkipBtn = isHovered || isSkipped
  const showMoveButtons = isHovered && (onMoveUp !== undefined || onMoveDown !== undefined)

  return (
    <div style={{ padding: ITEM_PADDING, paddingBottom: 0, cursor: 'pointer' }} onClick={onClick}>
      <div style={{
        position: 'relative',
        border: `2px solid ${isSelected ? 'var(--mantine-color-blue-5)' : 'transparent'}`,
        borderRadius: 4,
      }}>
        <div style={{ overflow: 'hidden', borderRadius: 2, background: 'var(--mantine-color-gray-1)' }}>
          {src ? (
            <img
              src={src}
              alt={`page ${page}`}
              style={{ width: '100%', display: 'block', opacity: isSkipped ? 0.3 : 1, transform: imgTransform }}
              draggable={false}
            />
          ) : (
            <div style={{ width: '100%', height: thumbHeight, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
              {pageCache.isLoading(pdfPath, page) && <Loader size="xs" />}
            </div>
          )}
        </div>
        {showRotateBtn && (
          <div
            onClick={(e) => { e.stopPropagation(); onRotate() }}
            style={{
              position: 'absolute', top: 3, left: 3,
              width: 16, height: 16, borderRadius: 3,
              background: isRotated ? 'var(--mantine-color-blue-6)' : 'rgba(0,0,0,0.45)',
              display: 'flex', alignItems: 'center', justifyContent: 'center',
              cursor: 'pointer', color: 'white',
            }}
          >
            <IconRotateClockwise size={10} stroke={3} />
          </div>
        )}
        {showSkipBtn && (
          <div
            onClick={(e) => { e.stopPropagation(); onToggleSkip() }}
            style={{
              position: 'absolute', top: 3, right: 3,
              width: 16, height: 16, borderRadius: 3,
              background: isSkipped ? 'var(--mantine-color-orange-6)' : 'rgba(0,0,0,0.45)',
              display: 'flex', alignItems: 'center', justifyContent: 'center',
              cursor: 'pointer', color: 'white',
            }}
          >
            <IconX size={10} stroke={3} />
          </div>
        )}
        {showMoveButtons && (
          <>
            <div
              onClick={(e) => { e.stopPropagation(); if (canMoveUp) onMoveUp?.() }}
              style={{
                position: 'absolute', bottom: 3, left: 3,
                width: 16, height: 16, borderRadius: 3,
                background: 'rgba(0,0,0,0.45)',
                display: 'flex', alignItems: 'center', justifyContent: 'center',
                cursor: canMoveUp ? 'pointer' : 'default',
                color: 'white',
                opacity: canMoveUp ? 1 : 0.3,
              }}
            >
              <IconArrowUp size={10} stroke={3} />
            </div>
            <div
              onClick={(e) => { e.stopPropagation(); if (canMoveDown) onMoveDown?.() }}
              style={{
                position: 'absolute', bottom: 3, right: 3,
                width: 16, height: 16, borderRadius: 3,
                background: 'rgba(0,0,0,0.45)',
                display: 'flex', alignItems: 'center', justifyContent: 'center',
                cursor: canMoveDown ? 'pointer' : 'default',
                color: 'white',
                opacity: canMoveDown ? 1 : 0.3,
              }}
            >
              <IconArrowDown size={10} stroke={3} />
            </div>
          </>
        )}
      </div>
      <div style={{
        textAlign: 'center',
        fontSize: 11,
        color: isSkipped ? 'var(--mantine-color-gray-5)' : 'var(--mantine-color-gray-7)',
        height: LABEL_HEIGHT,
        lineHeight: `${LABEL_HEIGHT}px`,
      }}>
        {label}
      </div>
    </div>
  )
}

import { useRef, useEffect } from 'react'
import { TransformWrapper, TransformComponent, ReactZoomPanPinchRef } from 'react-zoom-pan-pinch'
import { Center, Loader } from '@mantine/core'
import * as pageCache from '../hooks/pageCache'

const DETAIL_WIDTH = 1400

interface Props {
  pdfPath: string
  pageNum: number
  pageCount: number
  rotation?: number
  onNavigate: (page: number) => void
  onToggleSkip?: () => void
  onRotate?: () => void
}

export default function DetailPanel({ pdfPath, pageNum, pageCount, rotation = 0, onNavigate, onToggleSkip, onRotate }: Props) {
  pageCache.usePageCacheRender()
  const transformRef = useRef<ReactZoomPanPinchRef>(null)

  useEffect(() => {
    pageCache.load(pdfPath, pageNum, DETAIL_WIDTH)
    if (pageNum > 1) pageCache.load(pdfPath, pageNum - 1, DETAIL_WIDTH) // prefetch previous page
    if (pageNum < pageCount) pageCache.load(pdfPath, pageNum + 1, DETAIL_WIDTH) // prefetch next page
  }, [pdfPath, pageNum, pageCount])

  useEffect(() => {
    transformRef.current?.resetTransform()
  }, [pageNum, rotation])

  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return
      if (e.key === 'ArrowLeft') {
        e.preventDefault()
        if (pageNum > 1) onNavigate(pageNum - 1)
      } else if (e.key === 'ArrowRight') {
        e.preventDefault()
        if (pageNum < pageCount) onNavigate(pageNum + 1)
      } else if (e.key === 'Delete' || e.key === 'Backspace') {
        e.preventDefault()
        onToggleSkip?.()
      } else if (e.key === 'r') {
        e.preventDefault()
        onRotate?.()
      }
    }
    window.addEventListener('keydown', handler)
    return () => window.removeEventListener('keydown', handler)
  }, [pageNum, pageCount, onNavigate, onToggleSkip, onRotate])

  const cachedWidth = pageCache.getCachedWidth(pdfPath, pageNum)
  const src = cachedWidth !== undefined && cachedWidth >= DETAIL_WIDTH
    ? pageCache.getSrc(pdfPath, pageNum)
    : undefined

  return (
    <div
      style={{
        flex: 1,
        height: '100%',
        overflow: 'hidden',
        position: 'relative',
        background: 'var(--mantine-color-gray-1)',
        padding: 8,
      }}
    >
      {pageCache.isLoading(pdfPath, pageNum) && (
        <Center style={{ position: 'absolute', inset: 0, zIndex: 1 }}>
          <Loader />
        </Center>
      )}
      {src && (
        <TransformWrapper ref={transformRef} centerOnInit minScale={0.1} maxScale={8}>
          <TransformComponent
            wrapperStyle={{ width: '100%', height: '100%' }}
            contentStyle={{ display: 'flex', alignItems: 'center', justifyContent: 'center' }}
          >
            <img
              src={src}
              alt={`Page ${pageNum}`}
              draggable={false}
              style={{ maxWidth: '100%', maxHeight: '100%', display: 'block', userSelect: 'none', transform: rotation ? `rotate(${rotation}deg)` : undefined }}
            />
          </TransformComponent>
        </TransformWrapper>
      )}
    </div>
  )
}

import { ITEM_PADDING, HEADER_HEIGHT } from '../../constants'
import { PendingFocusHandle } from './usePendingFocus'
import ClippedPath from './ClippedPath'

interface Props {
  filename: string
  onChange: (name: string) => void
  firstPosition: number
  focus: PendingFocusHandle
  folder: string | null
  onPickFolder: () => void
  isDuplicate: boolean
}

export default function OutputFileHeader({
  filename, onChange, firstPosition, focus, folder, onPickFolder, isDuplicate,
}: Props) {
  const shouldFocus = focus.pendingFocus?.afterPosition === firstPosition - 1
  const cursorPos = focus.pendingFocus?.cursorPos ?? 0
  return (
    <div
      style={{
        margin: `4px ${ITEM_PADDING}px`,
        height: HEADER_HEIGHT - 8,
        padding: '4px 6px',
        background: 'var(--mantine-color-white)',
        border: `1px solid ${isDuplicate ? 'var(--mantine-color-red-5)' : 'var(--mantine-color-gray-3)'}`,
        borderRadius: 4,
        display: 'flex',
        flexDirection: 'column',
        justifyContent: 'space-between',
      }}
    >
      <div style={{ display: 'flex', alignItems: 'center', gap: 2 }}>
        <input
          ref={(el) => {
            if (el && shouldFocus) {
              el.focus()
              el.setSelectionRange(cursorPos, cursorPos)
              focus.clear()
            }
          }}
          type="text"
          value={filename}
          onChange={(e) => onChange(e.target.value)}
          placeholder="filename"
          style={{
            flex: 1,
            border: 'none',
            outline: 'none',
            background: 'transparent',
            fontSize: 12,
            fontWeight: 500,
            color: isDuplicate ? 'var(--mantine-color-red-7)' : 'inherit',
            minWidth: 0,
          }}
        />
        <span style={{ fontSize: 12, color: 'var(--mantine-color-dimmed)', flexShrink: 0 }}>.pdf</span>
      </div>
      <ClippedPath path={folder} onClick={onPickFolder} />
    </div>
  )
}

import { useRef, useLayoutEffect, useState } from 'react'
import { Tooltip } from '@mantine/core'

interface Props {
  path: string | null
  onClick: () => void
  placeholder?: string
}

// Displays a filesystem path, anchored to its right end so the filename is always visible.
// Uses scrollLeft (rather than direction:rtl) to avoid Unicode BiDi issues with the leading slash.
export default function ClippedPath({ path, onClick, placeholder = 'Choose folder…' }: Props) {
  const ref = useRef<HTMLDivElement>(null)
  const [clipped, setClipped] = useState(false)

  // Runs before paint to avoid a flash of the unscrolled (left-anchored) path.
  useLayoutEffect(() => {
    const el = ref.current
    if (!el) return
    const overflows = el.scrollWidth > el.clientWidth
    setClipped(overflows)
    if (overflows) el.scrollLeft = el.scrollWidth
  }, [path])

  const inner = (
    <div style={{ position: 'relative' }}>
      {/* Overlay '…' at the left edge to signal that the path is truncated. */}
      {clipped && (
        <span style={{
          position: 'absolute', left: 0, fontSize: 11, pointerEvents: 'none',
          color: 'var(--mantine-color-gray-6)',
          background: 'var(--mantine-color-white)',
          paddingRight: 1,
        }}>…</span>
      )}
      <div
        ref={ref}
        onClick={onClick}
        style={{
          fontSize: 11,
          color: path ? 'var(--mantine-color-gray-6)' : 'var(--mantine-color-dimmed)',
          cursor: 'pointer',
          whiteSpace: 'nowrap',
          overflow: 'hidden',
        }}
      >
        {path ?? placeholder}
      </div>
    </div>
  )

  return clipped && path
    ? <Tooltip label={path} openDelay={500}>{inner}</Tooltip>
    : inner
}

